using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    private static Godot.Collections.Array<string> LayerIds(GArray layers){var ids=new Godot.Collections.Array<string>();foreach(var value in layers)ids.Add(value.As<Resource>().Get("id").AsString());return ids;}
    private Settings RenderRequest(Control owner)=>new(){["document"]=Document(owner),["version"]=owner.Get("_edit_version")};
    private static bool CurrentRender(Control owner,Settings request)=>request["document"].AsGodotObject()==Document(owner)&&request["version"].AsInt64()==owner.Get("_edit_version").AsInt64();
    public void prepare_render_layers(Control owner,GArray ids){var temporary=_documents.snapshot(Document(owner));var keep=selected_ids_with_relatives(owner,ids);var layers=temporary.Get("layers").AsGodotArray();for(int i=layers.Count-1;i>=0;i--)if(!keep.ContainsKey(layers[i].As<Resource>().Get("id").AsString()))layers.RemoveAt(i);_renderer.sync(Renderer(owner),temporary);}
    public void restore_render_layers(Control owner){var renderer=Renderer(owner);renderer.Set("_topology","_restore_");_renderer.sync(renderer,Document(owner));}
    public Settings prepare_merge(Control owner){var roots=_documents.selected_roots(Document(owner),Canvas(owner).Get("selected").AsGodotArray());if(roots.Count==0)return new Settings();owner.Get("status").As<Label>().Text="Merging layers…";var request=RenderRequest(owner);request["ids"]=LayerIds(roots);return request;}
    public void complete_merge(Control owner,Settings request,Image? bitmap){if(!CurrentRender(owner,request))return;if(bitmap==null||bitmap.IsEmpty()){owner.Get("status").As<Label>().Text="Could not merge those layers.";return;}var merged=basic_from_image(owner,bitmap,"Merged layer");var ids=request["ids"].AsGodotArray();Action(owner,()=>{remove_roots(owner,ids);Document(owner).Get("layers").AsGodotArray().Add(merged);var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();selected.Add(merged.Get("id"));});owner.Get("status").As<Label>().Text="Merged "+ids.Count+" layer(s) into an editable basic layer";}
    public Settings prepare_rasterize(Control owner)
    {
        if(owner.Get("_rasterizing").AsBool())return new Settings();var targets=new GArray();foreach(var value in _documents.selected_roots(Document(owner),Canvas(owner).Get("selected").AsGodotArray())){var layer=value.As<Resource>();string kind=layer.Get("kind").AsString();if(kind is not "image" and not "paint" and not "basic"||layer.Get("live_paint").AsGodotArray().Count>0||ScriptIs(ResourceValue(Get(layer.Get("properties").AsGodotDictionary(),"texture_material")),"res://Workspaces/ImageWorkspace/texture_material.gd"))targets.Add(layer);}if(targets.Count==0)return new Settings();owner.Set("_rasterizing",true);owner.Get("status").As<Label>().Text="Preparing layer for pixel editing…";var request=RenderRequest(owner);request["targets"]=targets;request["replacements"]=new Settings();return request;
    }
    public void collect_rasterized(Control owner,Settings request,Resource layer,Image? bitmap){if(CurrentRender(owner,request)&&bitmap!=null&&!bitmap.IsEmpty())request["replacements"].AsGodotDictionary()[layer.Get("id")]=basic_from_image(owner,bitmap,layer.Get("label").AsString());}
    public void complete_rasterize(Control owner,Settings request)
    {
        owner.Set("_rasterizing",false);if(!CurrentRender(owner,request))return;var replacements=request["replacements"].AsGodotDictionary();if(replacements.Count>0)Action(owner,()=>{var document=Document(owner);var layers=document.Get("layers").AsGodotArray();foreach(var id in replacements.Keys){var original=_documents.layer_for_id(document,id.AsString());int index=layers.IndexOf(original!);remove_roots(owner,new GArray{id});layers.Insert(Math.Clamp(index,0,layers.Count),replacements[id]);}var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();foreach(var replacement in replacements.Values)selected.Add(replacement.As<Resource>().Get("id"));});owner.Get("status").As<Label>().Text="Layer is ready for painting and erasing";
    }
    public Settings prepare_crop(Control owner,Rect2 bounds,Vector2[] polygon)
    {
        var document=Document(owner);var size=document.Get("canvas_size").AsVector2I();var clipped=bounds.Intersection(new Rect2(Vector2.Zero,(Vector2)size));if(clipped.Size.X<1||clipped.Size.Y<1)return new Settings();var start=((Vector2I)clipped.Position.Floor()).Clamp(Vector2I.Zero,size);var end=((Vector2I)clipped.End.Ceil()).Clamp(Vector2I.Zero,size);var region=new Rect2I(start,end-start);var canvas=Canvas(owner);if(owner.Get("_crop_canvas").AsBool()){Action(owner,()=>{document.Set("canvas_size",region.Size);foreach(var value in _documents.children(document,"")){var layer=value.As<Resource>();layer.Set("position",layer.Get("position").AsVector2()-(Vector2)region.Position);}});_canvas.clear_selection(canvas);_canvas.fit(canvas);owner.Get("status").As<Label>().Text="Cropped the image canvas";return new Settings();}var roots=_documents.selected_roots(document,canvas.Get("selected").AsGodotArray());if(roots.Count==0){owner.Get("status").As<Label>().Text="Select one or more layers to crop.";return new Settings();}owner.Get("status").As<Label>().Text="Cropping selected layers…";var request=RenderRequest(owner);request["ids"]=LayerIds(roots);request["roots"]=roots;request["region"]=region;request["spans"]=crop_spans(region,polygon);request["polygon"]=polygon.Length>0;request["action"]=owner.Get("_crop_action");request["replacements"]=new Settings();return request;
    }
    public bool collect_crop_image(Control owner,Settings request,Image? combined)
    {
        if(!CurrentRender(owner,request)||combined==null||combined.IsEmpty())return false;var region=request["region"].AsRect2I();using var extracted=combined.GetRegion(region);Image pixels=extracted;Image? masked=null;if(request["polygon"].AsBool()){masked=Image.CreateEmpty(region.Size.X,region.Size.Y,false,Image.Format.Rgba8);masked.Fill(Colors.Transparent);foreach(var value in request["spans"].AsGodotArray()){var span=value.AsRect2I();var local=new Rect2I(span.Position-region.Position,span.Size);masked.BlitRect(extracted,local,local.Position);}pixels=masked;}try{var layer=_layers.create("basic",Document(owner).Get("canvas_size").AsVector2I());layer.Set("label","Cropped selection");layer.Set("position",(Vector2)region.Position);layer.Set("dimensions",(Vector2)region.Size);var texture=ImageTexture.CreateFromImage(pixels);layer.Set("texture",texture);layer.Set("paint_base",texture);request["new_layer"]=layer;return true;}finally{masked?.Dispose();}
    }
    public void collect_crop_replacement(Control owner,Settings request,Resource layer,Image? bitmap)
    {
        if(!CurrentRender(owner,request)||bitmap==null||bitmap.IsEmpty())return;foreach(var span in request["spans"].AsGodotArray())bitmap.FillRect(span.AsRect2I(),Colors.Transparent);request["replacements"].AsGodotDictionary()[layer.Get("id")]=basic_from_image(owner,bitmap,layer.Get("label").AsString());
    }
    public void complete_crop(Control owner,Settings request)
    {
        if(!CurrentRender(owner,request))return;var replacements=request["replacements"].AsGodotDictionary();int action=request["action"].AsInt32();Action(owner,()=>{var document=Document(owner);var layers=document.Get("layers").AsGodotArray();if(action!=1)foreach(var id in request["ids"].AsGodotArray()){var original=_documents.layer_for_id(document,id.AsString());int index=layers.IndexOf(original!);remove_roots(owner,new GArray{id});if(replacements.ContainsKey(id))layers.Insert(Math.Clamp(index,0,layers.Count),replacements[id]);}var selected=Canvas(owner).Get("selected").AsGodotArray();selected.Clear();if(action!=2){var layer=request["new_layer"].As<Resource>();layers.Add(layer);selected.Add(layer.Get("id"));}else foreach(var replacement in replacements.Values)selected.Add(replacement.As<Resource>().Get("id"));});owner.Call("_set_tool","move");owner.Get("status").As<Label>().Text="Crop complete";
    }
}
